def load() -> pd.DataFrame:
    import pandas as pd
    path = 'data/legal/input/csn-data-book-2024-csv/CSVs/2024_CSN_Report_Categories.csv'
    # Try common encodings for Windows-exported CSVs
    for enc in ['utf-8', 'utf-8-sig', 'cp1252', 'latin1']:
        try:
            df = pd.read_csv(path, encoding=enc)
            df['__encoding_used__'] = enc
            return pd.concat([df.head(5), df.tail(5)])
        except UnicodeDecodeError:
            continue
    # Fallback: replace undecodable bytes
    df = pd.read_csv(path, encoding='utf-8', encoding_errors='replace')
    df['__encoding_used__'] = 'utf-8(replace)'
    return pd.concat([df.head(5), df.tail(5)])
